function makeTextTexture(text, { colorA, colorB, fontPx, tracking }) {
  const tempCanvas = document.createElement("canvas");
  const tempCtx = tempCanvas.getContext("2d");
  const fontStr = `900 ${fontPx}px 'Space Grotesk', 'Arial Black', sans-serif`;
  tempCtx.font = fontStr;

  let totalTextWidth = 0;
  const charWidths = [];
  for (const ch of text) {
    const w = tempCtx.measureText(ch).width;
    charWidths.push(w);
    totalTextWidth += w + tracking;
  }
  totalTextWidth -= tracking;

  const paddingX = Math.round(fontPx * 1.2);
  const width = Math.ceil(totalTextWidth + paddingX * 2);
  const height = Math.ceil(fontPx * 2.2);

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, width, height);
  ctx.textBaseline = "middle";
  ctx.font = fontStr;

  const startX = paddingX;
  const y = height / 2;

  const grad = ctx.createLinearGradient(startX, 0, startX + totalTextWidth, 0);
  grad.addColorStop(0, colorA);
  grad.addColorStop(0.5, "#FFFFFF");
  grad.addColorStop(1, colorB);

  ctx.save();
  ctx.fillStyle = "rgba(8, 4, 20, 0.95)";
  ctx.shadowColor = "rgba(0, 0, 0, 0.8)";
  ctx.shadowBlur = 8;
  let xx = startX;
  for (let i = 0; i < text.length; i++) {
    ctx.fillText(text[i], xx + 3, y + 6);
    xx += charWidths[i] + tracking;
  }
  ctx.restore();

  ctx.save();
  ctx.fillStyle = grad;
  ctx.shadowColor = colorB;
  ctx.shadowBlur = 36;
  xx = startX;
  for (let i = 0; i < text.length; i++) {
    ctx.fillText(text[i], xx, y);
    xx += charWidths[i] + tracking;
  }
  ctx.restore();

  ctx.save();
  ctx.fillStyle = grad;
  ctx.shadowColor = colorA;
  ctx.shadowBlur = 12;
  xx = startX;
  for (let i = 0; i < text.length; i++) {
    ctx.fillText(text[i], xx, y);
    xx += charWidths[i] + tracking;
  }
  ctx.restore();

  ctx.save();
  ctx.fillStyle = "rgba(255, 255, 255, 0.7)";
  xx = startX;
  for (let i = 0; i < text.length; i++) {
    ctx.fillText(text[i], xx, y - 2);
    xx += charWidths[i] + tracking;
  }
  ctx.restore();

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  tex.needsUpdate = true;
  return tex;
}

function buildArcGeometry(radius, fontHeight, arcRad, segments, yOffset = 0) {
  const positions = [];
  const uvs = [];
  const indices = [];
  const half = arcRad / 2;

  for (let i = 0; i <= segments; i++) {
    const frac = i / segments;
    const phi = -half + frac * arcRad;

    const sinPhi = Math.sin(phi);
    const cosPhi = Math.cos(phi);

    const x = radius * sinPhi;
    const z = radius * cosPhi;
    const yBase = yOffset;
    const yTop = yOffset + fontHeight;

    positions.push(x, yBase, z);

    positions.push(x, yTop, z + 0.05);

    uvs.push(frac, 0);
    uvs.push(frac, 1);
  }

  for (let i = 0; i < segments; i++) {
    const a0 = i * 2;
    const b0 = i * 2 + 1;
    const a1 = i * 2 + 2;
    const b1 = i * 2 + 3;
    indices.push(a0, b0, a1, a1, b0, b1);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  return geo;
}


function OrbitalGlobe() {
  const mountRef = useRef(null);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const isMobile = mount.clientWidth < 640;
    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(42, width / height, 0.1, 100);
    camera.position.set(0, 0.15, isMobile ? 10.5 : 9.2);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, isMobile ? 1.75 : 2));
    renderer.setSize(width, height);
    renderer.setClearColor(0x000000, 0);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0x241a4a, 0.9));
    const keyLight = new THREE.PointLight(0xff57d8, 11, 28);
    keyLight.position.set(-4, 3, 4.2);
    scene.add(keyLight);
    const fillLight = new THREE.PointLight(0x2fd0e8, 8, 28);
    fillLight.position.set(4.2, -1.8, 3.2);
    scene.add(fillLight);
    const rimLight = new THREE.PointLight(0x6a3dff, 3.5, 28);
    rimLight.position.set(0, -3.6, -3.6);
    scene.add(rimLight);

    const assembly = new THREE.Group();
    scene.add(assembly);

    const globeGeo = new THREE.IcosahedronGeometry(1.9, 2);
    const globeMat = new THREE.MeshStandardMaterial({
      //color: 0x2c3ad0,
      color: 0x7185FF,
      flatShading: true,
      roughness: 0.32,
      metalness: 0.55,
      emissive: new THREE.Color(0x160f3d),
      emissiveIntensity: 0.15,
    });
    const globe = new THREE.Mesh(globeGeo, globeMat);
    assembly.add(globe);

    const wireGeo = new THREE.IcosahedronGeometry(1.93, 2);
    const wireMat = new THREE.MeshBasicMaterial({ color: 0xffffff, wireframe: true, transparent: true, opacity: 0.07 });
    assembly.add(new THREE.Mesh(wireGeo, wireMat));

    const glowCanvas = document.createElement("canvas");
    glowCanvas.width = 256;
    glowCanvas.height = 256;
    const gctx = glowCanvas.getContext("2d");
    const grad = gctx.createRadialGradient(128, 128, 0, 128, 128, 128);
    grad.addColorStop(0, "rgba(138,107,255,0.55)");
    grad.addColorStop(0.5, "rgba(47,208,232,0.15)");
    grad.addColorStop(1, "rgba(0,0,0,0)");
    gctx.fillStyle = grad;
    gctx.fillRect(0, 0, 256, 256);
    const glowTex = new THREE.CanvasTexture(glowCanvas);
    const glowMat = new THREE.SpriteMaterial({ map: glowTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
    const glow = new THREE.Sprite(glowMat);
    glow.scale.set(8.2, 8.2, 1);
    glow.position.z = -0.8;
    scene.add(glow);

    const ringsGroup = new THREE.Group();
    assembly.add(ringsGroup);

    const textSegs = isMobile ? 90 : 160;

    function makeRing({ radius, fontHeight, arcDeg, yOffset, text, tracking, colorA, colorB, spin = 0, dotColor }) {
      const g = new THREE.Group();

      const guideGeo = new THREE.TorusGeometry(radius, 0.007, 8, 100);
      const guideMat = new THREE.MeshBasicMaterial({ color: colorB, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending });
      const guide = new THREE.Mesh(guideGeo, guideMat);
      guide.rotation.x = Math.PI / 2; // horizontal circle in XZ plane
      guide.position.y = yOffset;
      g.add(guide);

      const fontPx = isMobile ? 85 : 125;

      const tex = makeTextTexture(text, { colorA, colorB, fontPx, tracking });
      tex.wrapS = THREE.RepeatWrapping;

      const arcGeo = buildArcGeometry(radius, fontHeight, (arcDeg * Math.PI) / 180, textSegs, yOffset);
      const arcMat = new THREE.MeshBasicMaterial({
        map: tex,
        transparent: true,
        side: THREE.DoubleSide,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      });
      const arcMesh = new THREE.Mesh(arcGeo, arcMat);
      g.add(arcMesh);

      const dotsGroup = new THREE.Group();
      const dotPositions = [0.15, 0.62];
      dotPositions.forEach((t) => {
        const ang = t * Math.PI * 2;
        const dotGeo = new THREE.SphereGeometry(0.055, 12, 12);
        const dotMat = new THREE.MeshBasicMaterial({ color: dotColor });
        const dot = new THREE.Mesh(dotGeo, dotMat);
        dot.position.set(Math.cos(ang) * radius, yOffset, Math.sin(ang) * radius);
        dotsGroup.add(dot);
      });
      g.add(dotsGroup);

      g.rotation.x = 0;
      g.userData.spin = spin;
      g.userData.tex = tex;
      g.userData.dots = dotsGroup;
      ringsGroup.add(g);
      return g;
    }

    const ring1 = makeRing({
      radius: isMobile ? 3.3 : 3.45,
      fontHeight: isMobile ? 0.64 : 0.7,
      arcDeg: 140,
      yOffset: isMobile ? 0.32 : 0.42,
      text: "IECSE IECSE IECSE IECSE IECSE",
      tracking: 14,
      colorA: "#2FD0E8",
      colorB: "#5B8AFF",
      spin: isMobile ? 0.0024 : 0.0016,
      dotColor: 0xbfe8ff,
    });

    const ring2 = makeRing({
      radius: isMobile ? 2.6 : 2.80,
      fontHeight: isMobile ? 0.58 : 0.6,
      arcDeg: 130,
      yOffset: isMobile ? -0.40 : -0.52,
      text: "RECRUITMENTS 2026",
      tracking: 14,
      colorA: "#FF57D8",
      colorB: "#8A6BFF",
      spin: isMobile ? -0.0024 : -0.0016,
      dotColor: 0xd9c9ff,
    });

    const pointer = { x: 0, y: 0 };
    const targetRot = { x: 0, y: 0 };
    const currentRot = { x: 0, y: 0 };
    let raf = null;

    function onPointerMove(e) {
      const rect = mount.getBoundingClientRect();
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      pointer.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = ((clientY - rect.top) / rect.height) * 2 - 1;
      targetRot.y = pointer.x * 0.4;
      targetRot.x = -pointer.y * 0.26;
    }
    window.addEventListener("mousemove", onPointerMove);
    //window.addEventListener("touchmove", onPointerMove, { passive: true });

    function onResize() {
      const w = mount.clientWidth;
      const h = mount.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    }
    const ro = new ResizeObserver(onResize);
    ro.observe(mount);

    function animate() {
      raf = requestAnimationFrame(animate);

      currentRot.x += (targetRot.x - currentRot.x) * 0.06;
      currentRot.y += (targetRot.y - currentRot.y) * 0.06;

      assembly.rotation.x = currentRot.x * 0.4;
      assembly.rotation.y = currentRot.y * 0.4;
      assembly.position.y = 0;

      ringsGroup.children.forEach((g) => {
        if (g.userData.spin) {
          if (g.userData.tex) {
            g.userData.tex.offset.x += g.userData.spin * 0.5;
          }
          if (g.userData.dots) {
            g.userData.dots.rotation.y += g.userData.spin;
          }
        }
      });

      renderer.render(scene, camera);
    }
    animate();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", onPointerMove);
      window.removeEventListener("touchmove", onPointerMove);
      ro.disconnect();
      mount.removeChild(renderer.domElement);
      scene.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (obj.material.map) obj.material.map.dispose();
          obj.material.dispose();
        }
      });
      glowTex.dispose();
      renderer.dispose();
    };
  }, []);

  return <div ref={mountRef} className="w-full h-full" />;
}

