function focusHandlers() {
  return {
    onFocus: (e) => {
      e.target.style.borderColor = COLORS.violet;
      e.target.style.boxShadow = "0 0 0 3px rgba(138,107,255,0.18)";
    },
    onBlur: (e) => {
      e.target.style.borderColor = "rgba(255,255,255,0.10)";
      e.target.style.boxShadow = "none";
    },
  };
}

function TextInput(props) {
  return (
    <input
      {...props}
      {...focusHandlers()}
      className="w-full rounded-lg px-4 py-3 text-sm outline-none transition-all duration-200"
      style={{ ...inputBase, ...(props.style || {}) }}
    />
  );
}

